<script setup lang="ts">
import{ref,computed,watch,onMounted,onBeforeUnmount}from'vue';import{useSalesScope}from'./use-sales-scope';import{qualityExpenseEntry,type QualityExpenseEntry}from'./quality-source-entry';
const props=defineProps<{staff:any;clinicId:string;year:number;quarter:number;entry?:QualityExpenseEntry|null;blocked?:boolean}>(),emit=defineEmits(['edit','unauthorized','access-lost','return-quality','context-change']);
const input=ref(''),expense=ref<any>(null),loading=ref(false),error=ref(''),generation=ref(0),context=()=>JSON.stringify([props.staff.accountId,props.staff.employeeId,props.clinicId,props.year,props.quarter]),scope=useSalesScope(context);let controller:AbortController|null=null;
function clear(){generation.value++;controller?.abort();controller=null;expense.value=null;loading.value=false;error.value='';emit('context-change');}
const expensePeriod=computed(()=>{const m=/^(\d{4})-(\d{2})-/.exec(expense.value?.occurred_on||'');return m?m[1]+'Q'+Math.ceil(Number(m[2])/3):'';});
watch(input,clear,{flush:'sync'});
async function load(){if(props.blocked||!props.clinicId)return;clear();const id=input.value.trim().toLowerCase();if(!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(id)){error.value='请粘贴完整费用编号。';return;}const current=scope.begin('source',()=>JSON.stringify([input.value,generation.value])),own=new AbortController();controller=own;loading.value=true;const timer=setTimeout(()=>own.abort(),15000);try{const r=await fetch('/api/v1/quarter/expenses/'+id+'/source?'+new URLSearchParams({clinicId:props.clinicId}),{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(!current())return;if(!r.ok){if(r.status===401)emit('unauthorized');if(r.status===403)emit('access-lost');throw Error(b.message||'原费用读取失败。');}if(b.expense?.expense_id!==id||b.expense?.clinic_id!==props.clinicId||!Number.isSafeInteger(Number(b.expense.row_version))||Number(b.expense.row_version)<1)throw Error('费用回复与当前定位不匹配，未显示。');expense.value=b.expense;}catch(e){if(current())error.value=e instanceof Error?e.message:'原费用读取失败。';}finally{clearTimeout(timer);if(current.active())loading.value=false;if(controller===own)controller=null;}}
async function initial(){clear();input.value='';if(!props.entry)return;try{const target=qualityExpenseEntry(props.entry);if(target.clinicId!==props.clinicId||target.year!==props.year||target.quarter!==props.quarter)return;input.value=target.expenseId;await load();}catch(e){error.value=e instanceof Error?e.message:'费用定位无效。';}}
watch(()=>JSON.stringify([context(),props.entry]),()=>{void initial();},{flush:'sync'});
function edit(){if(!props.blocked&&!loading.value&&expense.value)emit('edit',JSON.parse(JSON.stringify(expense.value)));}
function back(){if(!props.blocked&&!loading.value&&props.entry)emit('return-quality');}
function isCurrent(value:any){return!!expense.value&&expense.value.expense_id===value.expense_id&&expense.value.clinic_id===value.clinic_id&&Number(expense.value.row_version)===Number(value.row_version);}
onMounted(initial);onBeforeUnmount(clear);defineExpose({refresh:load,isCurrent});
</script>
<template><section class="b-card q-block expense-source"><h2>按编号定位原费用</h2><p>财务可粘贴交接的费用完整编号，在当前诊所中核对原记录。定位不登记费用，不支付，也不自动关闭资料问题。</p><form @submit.prevent="load"><label>费用完整编号<input v-model="input" :disabled="blocked||loading" maxlength="36" autocomplete="off"/></label><button class="b-button outline" :disabled="blocked||loading||!clinicId">{{loading?'正在定位…':'定位 / 重读原费用'}}</button></form><div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="!expense&&!loading&&!error">请先输入编号并定位。</p><article v-if="expense"><strong>{{expense.category}} · ¥{{expense.amount}}</strong><p>完整编号：{{expense.expense_id}}<br/>实际发生日期：{{expense.occurred_on}} · 当前第{{expense.row_version}}版<br/>凭据：{{expense.voucher_reference||'待补'}}<br/>凭据说明：{{expense.voucher_note||'无'}}<br/>待核实：{{expense.pending_note||'无待补事项'}}</p><p v-if="entry?.expenseId===expense.expense_id&&Number(expense.row_version)!==entry.version" class="b-alert warning">原费用已更新（问题查看时第{{entry.version}}版）；本次显示当前版本，请返回资料问题重新核实。</p><p v-if="expensePeriod&&expensePeriod!==year+'Q'+quarter" class="b-alert warning">本费用发生于{{expensePeriod}}，当前筛选为{{year}}Q{{quarter}}；本次按编号定位，不改变费用期间归属。</p><button class="b-button outline" :disabled="blocked||loading" @click="edit">按原流程核实更正此费用</button></article><button v-if="entry" class="b-button outline" :disabled="blocked||loading" @click="back">返回原资料问题</button></section></template>
<style scoped>.expense-source form{display:flex;align-items:end;gap:14px;flex-wrap:wrap;margin:18px 0}.expense-source form label{flex:1;min-width:240px}.expense-source article{padding:16px;background:#f4f7f2;border-radius:10px;margin:16px 0}.expense-source p{line-height:1.9;overflow-wrap:anywhere}.expense-source>.b-button{margin-top:12px}</style>


